/// 会话指向哪里。与协议 `SessionId` 的 oneof 分支一一对应。
enum ImSessionTargetKind {
  /// 私聊。点进去是聊天页。
  private,

  /// 折叠入口。点进去是二级会话列表。
  fold,

  /// 系统消息入口。
  system,

  /// 群聊。界面没有分支。
  group,

  /// 客服。界面没有分支。
  customer,
  unknown,
}

/// 设置页的一项。
class ImSetting {
  /// 协议里 settings 是 `map<int32, Setting>`，这是 key。写回时要用它。
  final int key;
  final String? title;
  final String? subtitle;

  /// 开关型：当前是否打开。非开关型为 `None`。
  final bool? switchOn;

  /// 选择型：当前选中项在 [`Self::options`] 里的下标。
  final int? selectedIndex;
  final List<ImSettingOption> options;

  /// 跳转型的去向。其余形态为 `None`。
  final ImSettingRedirect? redirect;

  const ImSetting({
    required this.key,
    this.title,
    this.subtitle,
    this.switchOn,
    this.selectedIndex,
    required this.options,
    this.redirect,
  });

  @override
  int get hashCode =>
      key.hashCode ^
      title.hashCode ^
      subtitle.hashCode ^
      switchOn.hashCode ^
      selectedIndex.hashCode ^
      options.hashCode ^
      redirect.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ImSetting &&
          runtimeType == other.runtimeType &&
          key == other.key &&
          title == other.title &&
          subtitle == other.subtitle &&
          switchOn == other.switchOn &&
          selectedIndex == other.selectedIndex &&
          options == other.options &&
          redirect == other.redirect;
}

/// 选择型设置的一个可选项。
class ImSettingOption {
  final String? title;

  /// 写回时传这个值，不是下标。
  final int value;

  const ImSettingOption({
    this.title,
    required this.value,
  });

  @override
  int get hashCode => title.hashCode ^ value.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ImSettingOption &&
          runtimeType == other.runtimeType &&
          title == other.title &&
          value == other.value;
}

/// 界面要主动打开的那几个设置页。
///
/// 协议的 `ImSettingType` 有二十多个取值，界面只会主动开这四个（其余的
/// 由 [`ImSettingRedirect::parent_setting_type`] 带过来）。导成枚举而不是
/// 让 Dart 写死 0 / 17 / 18 / 19——那四个数字在协议里相邻且无规律。
enum ImSettingPage {
  /// 全部私信设置。
  all,

  /// 「回复我的」的通知设置。
  replyMe,

  /// 「@我的」的通知设置。
  atMe,

  /// 「收到的赞」的通知设置。
  receiveLike,
}

/// 跳转型设置的去向，已摊平。按哪个字段有值分支，顺序与基线一致：
/// 子设置页 → 弹窗选择 → 外部页 → 设置页 url。
///
/// **不带子设置树。** 基线读它只为算一行右侧文字，那段规则在 Rust 侧
/// 算完了，结果是 [`Self::trailing_text`]。
class ImSettingRedirect {
  /// 子设置页的类型，拿它开下一页。
  final int? parentSettingType;
  final String? pageUrl;
  final String? otherUrl;

  /// 弹窗选择的可选项。非该形态时为空。
  final List<ImSettingOption> windowOptions;
  final int? windowSelectedIndex;
  final String? selectedSummary;

  /// 这一行右侧显示什么。已按基线的三级回退算好。
  final String? trailingText;

  const ImSettingRedirect({
    this.parentSettingType,
    this.pageUrl,
    this.otherUrl,
    required this.windowOptions,
    this.windowSelectedIndex,
    this.selectedSummary,
    this.trailingText,
  });

  @override
  int get hashCode =>
      parentSettingType.hashCode ^
      pageUrl.hashCode ^
      otherUrl.hashCode ^
      windowOptions.hashCode ^
      windowSelectedIndex.hashCode ^
      selectedSummary.hashCode ^
      trailingText.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ImSettingRedirect &&
          runtimeType == other.runtimeType &&
          parentSettingType == other.parentSettingType &&
          pageUrl == other.pageUrl &&
          otherUrl == other.otherUrl &&
          windowOptions == other.windowOptions &&
          windowSelectedIndex == other.windowSelectedIndex &&
          selectedSummary == other.selectedSummary &&
          trailingText == other.trailingText;
}

